const envelope = $json.body ?? {};
const payload = envelope.payload && typeof envelope.payload === 'object' && !Array.isArray(envelope.payload) ? envelope.payload : {};
const validationErrors = [];
if (envelope.type !== 'lead.qualified') validationErrors.push('invalid_event_type');
if (!envelope.id || !envelope.tenantId || !envelope.aggregateId || !envelope.occurredAt) validationErrors.push('invalid_envelope');
if (!payload.conversationId) validationErrors.push('missing_conversation_id');
return [{ json: {
  valid: validationErrors.length === 0,
  validationErrors,
  eventId: envelope.id ?? null,
  tenantId: envelope.tenantId ?? null,
  leadId: envelope.aggregateId ?? null,
  conversationId: payload.conversationId ?? null,
  score: payload.score ?? null,
  temperature: payload.temperature ?? null
} }];

const event = $('Validar Evento Lead Qualified').item.json;
const lead = $('Buscar Lead no Backend').item.json.data;
const conversation = $json.data;
const profile = lead?.profile && typeof lead.profile === 'object' && !Array.isArray(lead.profile) ? lead.profile : {};
const conversationSummary = conversation?.summary && typeof conversation.summary === 'object' && !Array.isArray(conversation.summary) ? conversation.summary : {};
const to = String($env.BROKER_NOTIFICATION_PHONE ?? '').replace(/\D/g, '');
const templateName = String($env.META_BROKER_TEMPLATE_NAME ?? '').trim();
const languageCode = String($env.META_TEMPLATE_LANGUAGE ?? 'pt_BR').trim();
const backofficeBaseUrl = String($env.BACKOFFICE_BASE_URL ?? '').replace(/\/$/, '');

const intentLabels = {
  BUY_PROPERTY: 'Compra', RENT_PROPERTY: 'Locacao', SELL_PROPERTY: 'Venda', PROPERTY_INFO: 'Informacoes de imovel',
  SCHEDULE_VISIT: 'Agendamento de visita', FINANCING_QUESTION: 'Financiamento', HUMAN_REQUEST: 'Atendimento humano',
  GENERAL_QUESTION: 'Duvida geral', UNKNOWN: 'Nao identificada'
};
const list = (value) => Array.isArray(value) ? (value.filter(Boolean).join(' / ') || 'Nao informado') : (value ? String(value) : 'Nao informado');
const scalar = (value) => value === undefined || value === null || value === '' ? 'Nao informado' : String(value);
const money = (value) => {
  const number = Number(value);
  return Number.isFinite(number) ? new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format(number) : null;
};
const minBudget = money(profile.minPrice);
const maxBudget = money(profile.maxPrice);
const budget = minBudget && maxBudget ? `${minBudget} a ${maxBudget}` : (maxBudget ? `Ate ${maxBudget}` : (minBudget ? `A partir de ${minBudget}` : 'Nao informado'));
const intent = scalar(lead?.intent ?? conversationSummary.intent ?? 'UNKNOWN');
const conversationRef = backofficeBaseUrl ? `${backofficeBaseUrl}/conversations/${event.conversationId}` : event.conversationId;
const summary = [
  'NOVO LEAD QUALIFICADO', '',
  `Nome: ${scalar(lead?.name ?? profile.name)}`,
  `Telefone: ${scalar(lead?.phone)}`,
  `Intencao: ${intentLabels[intent] ?? intent}`,
  `Tipo: ${scalar(profile.propertyType)}`,
  `Regiao: ${list([profile.city, ...(profile.neighborhoods ?? [])].filter(Boolean))}`,
  `Orcamento: ${budget}`,
  `Quartos: ${profile.minBedrooms === undefined ? 'Nao informado' : `${profile.minBedrooms}+`}`,
  `Pagamento: ${scalar(profile.paymentMethod)}`,
  `Prazo: ${profile.purchaseTimelineDays === undefined ? 'Nao informado' : `Ate ${profile.purchaseTimelineDays} dias`}`,
  `Imoveis apresentados: ${list(conversationSummary.presentedPropertyIds)}`,
  `Lead Score: ${scalar(lead?.score ?? event.score)}/100`,
  `Classificacao: ${scalar(lead?.temperature ?? event.temperature)}`,
  `Proximo passo: ${scalar(conversationSummary.nextStep)}`,
  `Conversa: ${scalar(conversationRef)}`
].join('\n').slice(0, 1000);
const validationErrors = [];
if (!lead || !conversation) validationErrors.push('missing_backend_data');
if (lead?.id !== event.leadId || conversation?.id !== event.conversationId || conversation?.leadId !== event.leadId) validationErrors.push('inconsistent_backend_data');
if (!/^\d{10,15}$/.test(to)) validationErrors.push('invalid_broker_phone');
if (!templateName) validationErrors.push('missing_broker_template');
if (!/^[a-z]{2}(?:_[A-Z]{2})?$/.test(languageCode)) validationErrors.push('invalid_language');
return [{ json: { valid: validationErrors.length === 0, validationErrors, eventId: event.eventId, tenantId: event.tenantId, to, templateName, languageCode, summary } }];
